export function initElectronMenuHandlers(){if(!window.electronAPI){console.log('Not running in Electron - menu handlers skipped');return;}
console.log('🔧 Setting up Electron menu handlers');createDraggableTitleBar();window.electronAPI.onExpandAllTesters(()=>{console.log('📤 Expand All Test Sections requested from menu');expandAllTestSections();});window.electronAPI.onCollapseAllTesters(()=>{console.log('📥 Collapse All Test Sections requested from menu');collapseAllTestSections();});}
function expandAllTestSections(){const testSections=document.querySelectorAll('.test-section');testSections.forEach(section=>{if(section.style.display==='none'&&section.id!=='integrated-tester-panel'){section.style.display='';}
section.classList.remove('collapsed');if(section.id){localStorage.setItem(`${section.id}-collapsed`,'false');}});console.log('✅ All test sections expanded');}
function collapseAllTestSections(){const testSections=document.querySelectorAll('.test-section');testSections.forEach(section=>{if(section.id==='integrated-tester-panel'&&section.style.display!=='none'){return;}
section.classList.add('collapsed');if(section.id){localStorage.setItem(`${section.id}-collapsed`,'true');}});console.log('✅ All test sections collapsed');}
function createDraggableTitleBar(){const header=document.querySelector('header');if(!header)return;const titleBar=document.createElement('div');titleBar.className='electron-title-bar';titleBar.style.cssText=`
        position: absolute;
        top: 0;
        left: 0;
        right: 60px;
        height: 24px;
        -webkit-app-region: drag;
        z-index: 100;
        cursor: grab;
        pointer-events: auto;
    `;titleBar.addEventListener('mousedown',()=>{titleBar.style.cursor='grabbing';});titleBar.addEventListener('mouseup',()=>{titleBar.style.cursor='grab';});header.insertBefore(titleBar,header.firstChild);console.log('✅ Draggable title bar element created');}